std::counting_semaphore<8> slots{8};      // at most 8 concurrent users

void handle(Request& r) {
    if (!slots.try_acquire_for(std::chrono::milliseconds(250)))
        return r.reject();                 // bounded wait, explicit shedding
    struct Permit {                            // releases on return or throw
        std::counting_semaphore<8>& s;
        ~Permit() { s.release(); }
    } permit{slots};
    serve(r);
}

