class Permit {
    sem_t& s_;
public:
    explicit Permit(sem_t& s) : s_(s) { while (sem_wait(&s_) == -1 && errno == EINTR) {} }
    ~Permit() { sem_post(&s_); }
    Permit(const Permit&) = delete;
    Permit& operator=(const Permit&) = delete;
};

